insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 1), 0, $txt$Se recomienda elaborar una lista de las tareas con manejo manual de cargas, indicando el puesto de trabajo y la actividad en que ocurre cada una.$txt$, $txt$Todavía no se ha elaborado una lista de las tareas en las que el personal levanta, baja, empuja, jala, transporta o estiba cargas manualmente.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 1), 1, $txt$Se recomienda elaborar por escrito una lista formal de las tareas con manejo manual de cargas que incluya todas las actividades de levantar, bajar, empujar, jalar, transportar y estibar cargas.$txt$, $txt$Se conocen de manera general las tareas con manejo manual de cargas, pero no existe una lista formal de las mismas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 1), 2, $txt$Se recomienda verificar que la lista de tareas con manejo manual de cargas esté completa y actualizarla.$txt$, $txt$Existe una lista de las tareas con manejo manual de cargas, pero no se ha revisado ni actualizado.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 1), 3, $txt$Se recomienda mantener actualizada la lista de tareas con manejo manual de cargas y revisarla cuando cambien las condiciones de trabajo.$txt$, $txt$Existe una lista actualizada de las tareas con manejo manual de cargas que cubre la mayoría de los puestos de trabajo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 1), 4, $txt$Se recomienda conservar la lista de tareas con manejo manual de cargas y actualizarla periódicamente.$txt$, $txt$La lista de tareas con manejo manual de cargas está completa, por escrito y actualizada.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 2), 0, $txt$Se recomienda pesar las cargas de cada estación de trabajo con manejo manual de cargas y registrar su peso promedio y máximo.$txt$, $txt$No se conoce el peso promedio ni el peso máximo de las cargas en cada estación de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 2), 1, $txt$Se recomienda medir y registrar el peso promedio y máximo en cada estación de trabajo con manejo manual de cargas.$txt$, $txt$Se tiene una idea aproximada del peso de las cargas, pero no se ha medido ni registrado.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 2), 2, $txt$Se recomienda completar el registro del peso de las cargas en todas las estaciones y puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se conoce el peso de las cargas en algunas estaciones o puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 2), 3, $txt$Se recomienda mantener actualizado el registro del peso de las cargas por estación de trabajo.$txt$, $txt$Se conoce el peso de las cargas en la mayoría de las estaciones de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 2), 4, $txt$Se recomienda mantener actualizado el registro del peso promedio y máximo de las cargas.$txt$, $txt$Se conoce y está registrado por escrito el peso promedio y máximo de las cargas en todas las estaciones de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 3), 0, $txt$Se recomienda mantener despejadas las áreas de trabajo y de tránsito donde se realiza manejo manual de cargas.$txt$, $txt$Las tareas de manejo manual de cargas se realizan en espacios reducidos o con obstáculos frecuentes.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 3), 1, $txt$Se recomienda revisar y despejar las áreas donde se realiza manejo manual de cargas.$txt$, $txt$Hay obstáculos o falta de espacio en varias de las áreas donde se realiza manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 3), 2, $txt$Se recomienda identificar y corregir los puntos con obstáculos en las áreas con manejo manual de cargas.$txt$, $txt$La mayoría de las áreas con manejo manual de cargas tienen espacio suficiente, pero todavía hay algunos puntos con obstáculos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 3), 3, $txt$Se recomienda mantener despejadas las áreas con manejo manual de cargas mediante inspecciones periódicas.$txt$, $txt$Las áreas de trabajo con manejo manual de cargas tienen espacio suficiente y están despejadas en la mayoría de los casos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 3), 4, $txt$Se recomienda verificar en las inspecciones de rutina que las áreas con manejo manual de cargas se mantengan despejadas.$txt$, $txt$Todas las áreas donde se realiza manejo manual de cargas tienen espacio suficiente y están libres de obstáculos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 4), 0, $txt$Se recomienda aplicar el Apéndice I (para levantar, bajar o transportar cargas) o el Apéndice II (para empujar o jalar) de la NOM-036-1-STPS-2018, según el caso.$txt$, $txt$No se usa ningún método para estimar el riesgo de las tareas de manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 4), 1, $txt$Se recomienda aplicar de manera formal la estimación del riesgo conforme al Apéndice I o II de la NOM-036-1-STPS-2018.$txt$, $txt$Se ha intentado aplicar algún método de estimación del riesgo en las tareas con manejo manual de cargas, pero de forma incompleta.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 4), 2, $txt$Se recomienda extender la aplicación de los métodos de estimación del riesgo a todas las tareas con manejo manual de cargas identificadas.$txt$, $txt$Se aplican métodos de estimación del riesgo en algunas tareas, pero no en todas las que involucran manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 4), 3, $txt$Se recomienda continuar aplicando los métodos de estimación del riesgo y documentar sus resultados.$txt$, $txt$Se aplican los métodos de estimación del riesgo (Apéndice I o II) en la mayoría de las tareas con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 4), 4, $txt$Se recomienda continuar aplicando y documentando la estimación del riesgo en todas las tareas con manejo manual de cargas.$txt$, $txt$Se aplican y quedan documentados los métodos de estimación del riesgo (Apéndice I o II) en todas las tareas con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 5), 0, $txt$Se recomienda registrar la frecuencia de levantamiento o traslado de cargas en cada actividad con manejo manual de cargas.$txt$, $txt$No se registra cuántas veces al día se levantan o trasladan cargas manualmente.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
