insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 5), 2, $txt$Se recomienda extender el registro de la frecuencia a todas las tareas y puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se registra la frecuencia en algunas estaciones o puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
