insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 6), 0, $txt$Se recomienda revisar que las cargas respeten los límites de peso permitidos según género y edad.$txt$, $txt$No se revisa si las cargas que se manejan manualmente respetan los límites de peso permitidos según género y edad.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
