insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 7), 0, $txt$Se recomienda elaborar un documento o plano que señale los puntos críticos de manejo manual de cargas.$txt$, $txt$No existe ningún documento ni plano que señale los puntos donde el manejo manual de cargas representa un riesgo mayor.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 7), 1, $txt$Se recomienda formalizar la documentación de los puntos críticos de manejo manual de cargas.$txt$, $txt$Existe documentación parcial o informal sobre los puntos críticos de manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 7), 2, $txt$Se recomienda completar la documentación de los puntos críticos para todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se cuenta con documentación de los puntos críticos en algunas áreas, pero no en todas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 7), 3, $txt$Se recomienda mantener actualizada la documentación de los puntos críticos de manejo manual de cargas.$txt$, $txt$Se cuenta con documentación de los puntos críticos para la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 7), 4, $txt$Se recomienda mantener actualizados los documentos y planos de los puntos críticos de manejo manual de cargas.$txt$, $txt$Se cuenta con documentación o planos completos de los puntos críticos de manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 8), 0, $txt$Se recomienda revisar y reorganizar las áreas con manejo manual de cargas.$txt$, $txt$No se ha ajustado la distribución de los procesos o materiales para evitar posturas forzadas o traslados innecesarios.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 8), 1, $txt$Se recomienda evaluar de forma integral la distribución de las áreas con manejo manual de cargas.$txt$, $txt$Se han hecho algunos ajustes puntuales en la distribución de procesos o materiales, sin un plan general.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
