insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 8), 3, $txt$Se recomienda completar la reubicación de procesos o materiales en todas las áreas con manejo manual de cargas.$txt$, $txt$Se han reubicado procesos o materiales en la mayoría de las áreas con manejo manual de cargas para evitar posturas forzadas o traslados innecesarios.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 8), 4, $txt$Se recomienda conservar la distribución actual de procesos y materiales y revisarla cuando cambien las condiciones de trabajo.$txt$, $txt$Los procesos y materiales de las áreas con manejo manual de cargas están distribuidos de forma que se evitan posturas forzadas y traslados innecesarios.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 9), 0, $txt$Se recomienda establecer pausas activas o periodos de descanso para las tareas repetitivas de manejo manual de cargas.$txt$, $txt$No hay pausas activas ni descansos programados para las tareas repetitivas de manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 9), 1, $txt$Se recomienda establecer por escrito un programa de pausas activas y descansos.$txt$, $txt$Las pausas o descansos se dan de manera informal, sin un programa establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 9), 2, $txt$Se recomienda extender el programa de pausas activas y descansos a todos los puestos de trabajo con manejo manual de cargas que lo necesiten.$txt$, $txt$Existen pausas o descansos, pero no para todas las actividades repetitivas con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 9), 3, $txt$Se recomienda documentar el programa de pausas activas y descansos y darle seguimiento.$txt$, $txt$El programa de pausas activas y descansos cubre la mayoría de las actividades repetitivas con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 9), 4, $txt$Se recomienda mantener el programa de pausas activas y descansos y revisarlo si cambian las condiciones de trabajo.$txt$, $txt$El programa de pausas activas y descansos para las actividades repetitivas con manejo manual de cargas está documentado y se aplica de forma constante.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 10), 0, $txt$Se recomienda llevar el control de la masa acumulada que maneja cada trabajador y asegurar que no exceda 10,000 kg por jornada de 8 horas para distancias menores a 10 m, o 6,000 kg por jornada de 8 horas para distancias no mayores a 20 m.$txt$, $txt$No se controla la masa total que maneja manualmente cada trabajador durante su jornada.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 10), 1, $txt$Se recomienda comparar formalmente la masa acumulada por trabajador con los límites de la norma.$txt$, $txt$Hay un control informal de la masa total que maneja cada trabajador, sin compararla con los límites de la norma.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 10), 2, $txt$Se recomienda extender el control de la masa acumulada a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se controla la masa total en algunos puestos de trabajo con manejo manual de cargas, pero no en todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 10), 3, $txt$Se recomienda mantener el control de la masa acumulada por trabajador y extenderlo a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se controla la masa total que maneja cada trabajador, dentro de los límites permitidos, en la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 1) and i.numero = 10), 4, $txt$Se recomienda mantener documentado el control de la masa acumulada por trabajador.$txt$, $txt$Se controla y queda documentado que ningún trabajador excede los límites de masa total por jornada.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 1), 'inexistente', 'apertura', $txt$No existe un proceso formal de identificación y clasificación de los puestos de trabajo con manejo manual de cargas, conforme a lo que exige el numeral 7.2 de la NOM-036-1-STPS-2018.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 1), 'minimo', 'apertura', $txt$El proceso de identificación y clasificación de los puestos de trabajo con manejo manual de cargas es Mínimo: la mayoría de los elementos que exige el numeral 7.2 de la NOM-036-1-STPS-2018 no están cubiertos.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 1), 'regular', 'apertura', $txt$El proceso de identificación y clasificación de los puestos de trabajo con manejo manual de cargas se encuentra en un nivel Regular: existen avances, pero persisten vacíos relevantes.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 1), 'aceptable', 'apertura', $txt$El proceso de identificación y clasificación de los puestos de trabajo con manejo manual de cargas presenta un nivel Aceptable, con puntos específicos por reforzar.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 1), 'optimo', 'apertura', $txt$El proceso de identificación y clasificación de los puestos de trabajo con manejo manual de cargas está consolidado.$txt$);
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 1), 0, $txt$Se recomienda incorporar equipos auxiliares manuales cuando el peso o la longitud de la carga dificulten su transporte.$txt$, $txt$No se cuenta con ningún equipo auxiliar (carretillas, diablos, patines) para el manejo cotidiano de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 1), 1, $txt$Se recomienda extender su uso a todas las tareas con manejo manual de cargas que lo requieran.$txt$, $txt$Se cuenta con algunos equipos auxiliares, pero no se usan de manera regular.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 1), 2, $txt$Se recomienda incorporar equipos auxiliares en todos los puestos de trabajo con manejo manual de cargas que lo requieran.$txt$, $txt$Se utilizan equipos auxiliares en algunos puestos de trabajo con manejo manual de cargas, pero no en todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 1), 3, $txt$Se recomienda mantener el uso de equipos auxiliares e incorporarlos en los puestos de trabajo con manejo manual de cargas que aún no cuentan con ellos.$txt$, $txt$Se utilizan equipos auxiliares en la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 1), 4, $txt$Se recomienda mantener el uso de equipos auxiliares en todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se utilizan equipos auxiliares (carretillas, diablos, patines) en todos los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 2), 0, $txt$Se recomienda verificar la estabilidad de la carga antes de cada traslado, para evitar que caiga del diablo, patín o carretilla.$txt$, $txt$No se evalúa la estabilidad de las cargas antes de transportarlas con equipo auxiliar.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 2), 1, $txt$Se recomienda establecer un procedimiento para verificar la estabilidad de la carga antes de cada traslado con equipo auxiliar.$txt$, $txt$La estabilidad de la carga se revisa de manera ocasional, sin un procedimiento establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 2), 2, $txt$Se recomienda verificar la estabilidad de la carga en todos los traslados con equipo auxiliar, como parte de un procedimiento establecido.$txt$, $txt$Se evalúa la estabilidad de la carga en algunos traslados con equipo auxiliar, pero no como parte de un procedimiento establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 2), 3, $txt$Se recomienda verificar la estabilidad de la carga en todos los traslados con equipo auxiliar.$txt$, $txt$Se evalúa la estabilidad de la carga en la mayoría de los traslados con equipo auxiliar.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 2), 4, $txt$Se recomienda mantener la verificación de la estabilidad de la carga antes de cada traslado.$txt$, $txt$Se evalúa y asegura la estabilidad de la carga antes de cada traslado con equipo auxiliar.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 3), 0, $txt$Se recomienda identificar y verificar la capacidad nominal de cada equipo, para no excederla.$txt$, $txt$No se conoce la capacidad de carga de los equipos auxiliares que se utilizan.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 3), 1, $txt$Se recomienda confirmar y registrar la capacidad nominal de cada equipo.$txt$, $txt$Se tiene una idea aproximada de la capacidad de los equipos auxiliares, pero no está verificada ni documentada.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 3), 2, $txt$Se recomienda identificar la capacidad de carga de todos los equipos auxiliares que se utilizan.$txt$, $txt$Se conoce la capacidad de carga de algunos equipos auxiliares, pero no de todos los que se utilizan.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 3), 3, $txt$Se recomienda completar y mantener actualizado el registro de la capacidad de carga de los equipos auxiliares.$txt$, $txt$Se conoce la capacidad de carga de la mayoría de los equipos auxiliares utilizados.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 3), 4, $txt$Se recomienda mantener la verificación de que no se exceda la capacidad nominal de los equipos auxiliares.$txt$, $txt$Se conoce la capacidad nominal de cada equipo auxiliar utilizado y se verifica que no se exceda.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 4), 0, $txt$Se recomienda mantener los pisos en condiciones seguras para el traslado de cargas.$txt$, $txt$Las superficies de rodamiento por donde circulan los equipos auxiliares no están niveladas, limpias ni libres de obstáculos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 4), 1, $txt$Se recomienda establecer una revisión periódica de las áreas donde se transportan cargas.$txt$, $txt$Las superficies de rodamiento pueden estar frecuentemente obstruidas y no existe una revisión constante de su estado.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 4), 2, $txt$Se recomienda mantener niveladas, limpias y despejadas las superficies de rodamiento en todas las áreas donde se transportan cargas.$txt$, $txt$Las superficies de rodamiento están en buenas condiciones y despejadas en algunas áreas, pero no en todas las que se usan para transportar cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 4), 3, $txt$Se recomienda verificar mediante inspecciones periódicas que las superficies de rodamiento se mantengan niveladas, limpias y libres de obstáculos.$txt$, $txt$Las superficies de rodamiento están niveladas, limpias y libres de obstáculos en la mayoría de las áreas donde se transportan cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 4), 4, $txt$Se recomienda mantener las superficies de rodamiento niveladas, limpias y libres de obstáculos mediante inspecciones de rutina.$txt$, $txt$Las superficies de rodamiento están niveladas, limpias y libres de obstáculos en todas las áreas donde se transportan cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 5), 0, $txt$Se recomienda verificar que el espacio disponible corresponda a las dimensiones de las cargas que se transportan, en especial en pasillos angostos.$txt$, $txt$Los pasillos de tránsito peatonal no tienen el espacio suficiente para maniobrar con cargas de forma segura.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 5), 1, $txt$Se recomienda realizar una revisión formal de los pasillos donde se transportan cargas.$txt$, $txt$Algunos pasillos de tránsito peatonal no permiten maniobrar con cargas de forma segura.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 5), 2, $txt$Se recomienda corregir los pasillos de tránsito que no permiten maniobrar con cargas de forma segura.$txt$, $txt$Los pasillos de tránsito permiten maniobras seguras con cargas en algunas áreas, pero no en todas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 5), 3, $txt$Se recomienda verificar periódicamente que todos los pasillos de tránsito permitan maniobras seguras con cargas.$txt$, $txt$Los pasillos de tránsito permiten maniobras seguras con cargas en la mayoría de las áreas donde se transportan cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 5), 4, $txt$Se recomienda mantener los pasillos de tránsito con espacio suficiente para maniobrar con cargas de forma segura.$txt$, $txt$Los pasillos de tránsito permiten maniobras seguras con cargas en todas las áreas donde se transportan cargas, incluidos los pasillos angostos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 6), 0, $txt$Se recomienda delimitar y señalizar las rampas, pendientes y plataformas para orientar el tránsito con cargas.$txt$, $txt$Las rampas, pendientes y plataformas no cuentan con ninguna señalización para su uso seguro.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 6), 1, $txt$Se recomienda estandarizar la señalización en todas las rampas, pendientes y plataformas que se usan para transportar cargas.$txt$, $txt$Hay señalización en algunas rampas o plataformas, pero de forma aislada y sin un criterio uniforme.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 6), 2, $txt$Se recomienda señalizar todas las rampas, pendientes y plataformas que se usan para transportar cargas.$txt$, $txt$Las rampas y plataformas cuentan con señalización en algunas áreas, pero no en todas las que se usan para transportar cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 6), 3, $txt$Se recomienda mantener y revisar periódicamente la señalización de rampas, pendientes y plataformas.$txt$, $txt$Las rampas, pendientes y plataformas cuentan con señalización adecuada en la mayoría de las áreas donde se transportan cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 6), 4, $txt$Se recomienda mantener en buen estado la señalización de rampas, pendientes y plataformas.$txt$, $txt$Todas las rampas, pendientes y plataformas que se usan para transportar cargas cuentan con señalización clara para su uso seguro.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 7), 0, $txt$Se recomienda verificar que los equipos auxiliares estén en condiciones seguras de operación antes de cada uso.$txt$, $txt$No se revisa el estado físico de los equipos auxiliares antes de usarlos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 7), 1, $txt$Se recomienda establecer un programa de revisión periódica del estado físico de los equipos auxiliares.$txt$, $txt$El estado físico de los equipos auxiliares se revisa de forma ocasional, sin un programa establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 7), 2, $txt$Se recomienda revisar el estado físico de todos los equipos auxiliares en uso.$txt$, $txt$Se revisa el estado físico de algunos equipos auxiliares, pero no de todos los que están en uso.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 7), 3, $txt$Se recomienda mantener el programa de revisión periódica y extenderlo a todos los equipos auxiliares.$txt$, $txt$Se revisa periódicamente el estado físico de la mayoría de los equipos auxiliares.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 7), 4, $txt$Se recomienda mantener la revisión del estado físico de los equipos auxiliares, de forma periódica y antes de cada uso.$txt$, $txt$Se revisa periódicamente, y antes de cada uso, el estado físico de todos los equipos auxiliares.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 8), 0, $txt$Se recomienda acomodar las cargas en el equipo auxiliar de manera que se mantenga su estabilidad durante el traslado.$txt$, $txt$Las cargas no se distribuyen de forma equilibrada en el equipo auxiliar durante el traslado.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 8), 1, $txt$Se recomienda definir un criterio de acomodo seguro de las cargas en el equipo auxiliar.$txt$, $txt$La distribución de la carga en el equipo auxiliar no está estandarizada ni sigue un criterio establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 8), 2, $txt$Se recomienda distribuir las cargas de forma equilibrada en todos los traslados con equipo auxiliar.$txt$, $txt$Las cargas se distribuyen de forma equilibrada en el equipo auxiliar en algunos traslados, pero no de forma constante.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 8), 3, $txt$Se recomienda distribuir las cargas de forma equilibrada en todos los traslados con equipo auxiliar.$txt$, $txt$Las cargas se distribuyen de forma equilibrada en el equipo auxiliar en la mayoría de los traslados.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 8), 4, $txt$Se recomienda mantener la distribución equilibrada de las cargas en todos los traslados con equipo auxiliar.$txt$, $txt$Las cargas se distribuyen de forma equilibrada en el equipo auxiliar en todos los traslados.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 9), 0, $txt$Se recomienda identificar los riesgos por condiciones térmicas o de iluminación en las rutas de traslado de cargas, ya que pueden incrementar el esfuerzo del trabajador.$txt$, $txt$No se identifican los riesgos por condiciones térmicas o de iluminación en las rutas de traslado de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 9), 1, $txt$Se recomienda documentar las condiciones térmicas y de iluminación de las rutas de traslado de cargas.$txt$, $txt$Se tiene una idea general de los riesgos por condiciones térmicas o de iluminación, pero no se ha realizado una identificación formal.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 9), 2, $txt$Se recomienda identificar los riesgos por condiciones térmicas o de iluminación en todas las rutas de traslado de cargas.$txt$, $txt$Se identifican los riesgos por condiciones térmicas o de iluminación en algunas rutas de traslado de cargas, pero no en todas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 9), 3, $txt$Se recomienda completar y mantener actualizada la identificación de los riesgos por condiciones térmicas o de iluminación en las rutas de traslado de cargas.$txt$, $txt$Se identifican los riesgos por condiciones térmicas o de iluminación en la mayoría de las rutas de traslado de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 9), 4, $txt$Se recomienda mantener documentados y actualizados los riesgos por condiciones térmicas o de iluminación en las rutas de traslado de cargas.$txt$, $txt$Se identifican y documentan los riesgos por condiciones térmicas o de iluminación en todas las rutas de traslado de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 10), 0, $txt$Se recomienda organizar el transporte de materiales, con equipos auxiliares o dividiendo las cargas, para que la masa total que transporta cada trabajador se mantenga dentro de los límites de la norma: 10,000 kg por jornada de 8 horas para distancias menores a 10 m, o 6,000 kg por jornada de 8 horas para distancias no mayores a 20 m.$txt$, $txt$No se controla la masa total que transporta cada trabajador por jornada.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 10), 1, $txt$Se recomienda comparar formalmente la masa total transportada por trabajador con los límites de la norma.$txt$, $txt$Hay un control informal de la masa total transportada, sin compararla con los límites de la norma.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 10), 2, $txt$Se recomienda extender el control de la masa total transportada a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se controla la masa total transportada en algunos puestos de trabajo con manejo manual de cargas, con o sin equipo auxiliar, pero no en todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 10), 3, $txt$Se recomienda mantener el control de la masa total transportada por jornada y extenderlo a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se controla que la masa total transportada por jornada se mantenga dentro de los límites permitidos en la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 2) and i.numero = 10), 4, $txt$Se recomienda mantener documentado el control de la masa total transportada por trabajador.$txt$, $txt$Se controla y queda documentado que ningún trabajador excede los límites de masa total por jornada en el transporte de materiales, con o sin equipo auxiliar.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 2), 'inexistente', 'apertura', $txt$No existe un proceso formal de uso de equipos auxiliares ni de control de las condiciones ambientales en el manejo manual de cargas, conforme a lo que exige el numeral 8.3 de la NOM-036-1-STPS-2018.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 2), 'minimo', 'apertura', $txt$El uso de equipos auxiliares y el control de las condiciones ambientales en el manejo manual de cargas se encuentran en un nivel Mínimo: la mayoría de las medidas que exige el numeral 8.3 de la NOM-036-1-STPS-2018 no están cubiertas.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 2), 'regular', 'apertura', $txt$El uso de equipos auxiliares y el control de las condiciones ambientales en el manejo manual de cargas se encuentran en un nivel Regular: existen avances, pero persisten vacíos relevantes.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 2), 'aceptable', 'apertura', $txt$El uso de equipos auxiliares y el control de las condiciones ambientales en el manejo manual de cargas presentan un nivel Aceptable, con puntos específicos por reforzar.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 2), 'optimo', 'apertura', $txt$El uso de equipos auxiliares y el control de las condiciones ambientales en el manejo manual de cargas están consolidados.$txt$);
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 1), 0, $txt$Se recomienda proporcionar capacitación específica en técnicas seguras de manipulación de cargas, con énfasis en la prevención de riesgos y de acuerdo con las tareas de cada puesto de trabajo.$txt$, $txt$El personal con tareas de manejo manual de cargas no ha recibido ninguna capacitación específica sobre técnicas seguras de manipulación.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 1), 1, $txt$Se recomienda formalizar la capacitación en manejo manual de cargas y ampliarla a todas las tareas y a todo el personal que las realiza.$txt$, $txt$Se ha impartido alguna capacitación informal sobre manejo manual de cargas, sin cubrir todas las tareas ni a todo el personal que las realiza.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 1), 2, $txt$Se recomienda extender la capacitación en técnicas seguras de manipulación a todo el personal con tareas de manejo manual de cargas.$txt$, $txt$Se capacita en técnicas seguras de manipulación a una parte del personal con tareas de manejo manual de cargas, pero no a todo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 1), 3, $txt$Se recomienda completar la capacitación en técnicas seguras de manipulación con el personal que aún no la ha recibido.$txt$, $txt$La mayoría del personal con tareas de manejo manual de cargas ha recibido capacitación específica en técnicas seguras de manipulación.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 1), 4, $txt$Se recomienda mantener la capacitación en técnicas seguras de manipulación para todo el personal con tareas de manejo manual de cargas.$txt$, $txt$Todo el personal con tareas de manejo manual de cargas ha recibido capacitación específica en técnicas seguras de manipulación.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 2), 0, $txt$Se recomienda llevar un registro con el nombre y el puesto de trabajo de los trabajadores capacitados, la fecha y los temas impartidos.$txt$, $txt$No existen registros de las capacitaciones impartidas sobre manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 2), 1, $txt$Se recomienda establecer un formato de registro para las capacitaciones sobre manejo manual de cargas.$txt$, $txt$Hay registros informales o incompletos de las capacitaciones sobre manejo manual de cargas, sin un formato establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 2), 2, $txt$Se recomienda registrar todas las capacitaciones impartidas sobre manejo manual de cargas.$txt$, $txt$Existen registros de algunas de las capacitaciones impartidas sobre manejo manual de cargas, pero no de todas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 2), 3, $txt$Se recomienda completar y mantener al día los registros de capacitación.$txt$, $txt$Existen registros actualizados de la mayoría de las capacitaciones impartidas sobre manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 2), 4, $txt$Se recomienda mantener actualizados los registros de capacitación, con nombre, puesto de trabajo, fecha y temas.$txt$, $txt$Existen registros actualizados de todas las capacitaciones impartidas sobre manejo manual de cargas, con nombre, puesto de trabajo, fecha y temas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 3), 0, $txt$Se recomienda estructurar la capacitación con instrucción teórica, entrenamiento práctico y evaluación de los conocimientos adquiridos.$txt$, $txt$La capacitación en manejo manual de cargas no incluye ningún componente teórico, práctico ni de evaluación.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 3), 1, $txt$Se recomienda integrar en la capacitación los componentes teórico, práctico y de evaluación.$txt$, $txt$La capacitación en manejo manual de cargas incluye solo uno o dos de los tres componentes (teórico, práctico o de evaluación).$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
