insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 3) and i.numero = 10), 4, $txt$Se recomienda mantener el enfoque integral de bienestar físico y psicológico del personal.$txt$, $txt$Se contempla de forma integral el bienestar físico y psicológico del personal en todas las actividades con esfuerzo físico.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 3), 'inexistente', 'apertura', $txt$No existe un proceso formal de capacitación, adiestramiento ni vigilancia a la salud del personal con tareas de manejo manual de cargas, conforme a lo que exige la NOM-036-1-STPS-2018 en sus Capítulos 9 y 10.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 3), 'minimo', 'apertura', $txt$La capacitación, el adiestramiento y la vigilancia a la salud del personal con tareas de manejo manual de cargas se encuentran en un nivel Mínimo: la mayoría de las medidas que exigen los Capítulos 9 y 10 de la NOM-036-1-STPS-2018 no están cubiertas.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 3), 'regular', 'apertura', $txt$La capacitación, el adiestramiento y la vigilancia a la salud del personal con tareas de manejo manual de cargas se encuentran en un nivel Regular: existen avances, pero persisten vacíos relevantes.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 3), 'aceptable', 'apertura', $txt$La capacitación, el adiestramiento y la vigilancia a la salud del personal con tareas de manejo manual de cargas presentan un nivel Aceptable, con puntos específicos por reforzar.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 3), 'optimo', 'apertura', $txt$La capacitación, el adiestramiento y la vigilancia a la salud del personal con tareas de manejo manual de cargas están consolidados.$txt$);
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 1), 0, $txt$Se recomienda documentar una política interna que establezca el compromiso de la organización con la prevención de estos riesgos.$txt$, $txt$No existe ninguna política interna por escrito en materia de prevención de riesgos ergonómicos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 1), 1, $txt$Se recomienda formalizar por escrito los lineamientos como una política interna de prevención de riesgos ergonómicos.$txt$, $txt$Existen algunos lineamientos informales sobre el tema, sin que estén documentados como política interna.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 1), 2, $txt$Se recomienda revisar la política interna de prevención de riesgos ergonómicos y completarla.$txt$, $txt$Existe una política interna por escrito, pero se desconoce si cubre todos los aspectos de la prevención de riesgos ergonómicos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 1), 3, $txt$Se recomienda completar y mantener actualizada la política interna de prevención de riesgos ergonómicos.$txt$, $txt$Existe una política interna por escrito que cubre la mayoría de los aspectos de la prevención de riesgos ergonómicos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 1), 4, $txt$Se recomienda mantener vigente la política interna de prevención de riesgos ergonómicos.$txt$, $txt$Existe una política interna por escrito, completa y vigente, en materia de prevención de riesgos ergonómicos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 2), 0, $txt$Se recomienda asignar esta responsabilidad a una persona o área específica.$txt$, $txt$No se ha designado a ningún responsable del cumplimiento de la NOM-036-1-STPS-2018.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 2), 1, $txt$Se recomienda designar oficialmente a un responsable del cumplimiento de la NOM-036-1-STPS-2018.$txt$, $txt$Hay una persona que atiende el tema de manera informal, sin que esté designada oficialmente.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 2), 2, $txt$Se recomienda definir con claridad las funciones y el alcance del responsable del cumplimiento de la norma.$txt$, $txt$Se ha designado a un responsable, pero sus funciones no están claramente definidas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 2), 3, $txt$Se recomienda formalizar la designación del responsable y mantenerla vigente.$txt$, $txt$Se ha designado a un responsable con funciones claras para el cumplimiento de la norma.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 2), 4, $txt$Se recomienda mantener vigente la designación formal del responsable del cumplimiento de la norma.$txt$, $txt$Se ha designado formalmente a un responsable, con funciones claras, para el cumplimiento de la NOM-036-1-STPS-2018.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 3), 0, $txt$Se recomienda asignar un presupuesto específico para este fin.$txt$, $txt$No se destina presupuesto para la adquisición de equipos auxiliares de carga.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 3), 1, $txt$Se recomienda incluir este gasto en la planeación presupuestal.$txt$, $txt$Se destina presupuesto de forma esporádica, sin planearlo con anticipación.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 3), 2, $txt$Se recomienda ampliar el presupuesto para cubrir todas las necesidades identificadas de equipos auxiliares de carga.$txt$, $txt$Se destina presupuesto para algunos equipos auxiliares de carga, pero no de forma consistente para todas las necesidades identificadas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 3), 3, $txt$Se recomienda cubrir con presupuesto todas las necesidades identificadas de equipos auxiliares de carga.$txt$, $txt$Se destina presupuesto para la mayoría de las necesidades identificadas de equipos auxiliares de carga.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 3), 4, $txt$Se recomienda mantener la planeación presupuestal para la adquisición de equipos auxiliares de carga.$txt$, $txt$Se destina y ejerce presupuesto de forma planeada para la adquisición de equipos auxiliares de carga.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 4), 0, $txt$Se recomienda llevar estos registros, conforme a lo que exige la norma.$txt$, $txt$No se mantienen registros de los diagnósticos, programas ni acciones en materia de ergonomía.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 4), 1, $txt$Se recomienda formalizar los registros de diagnósticos, programas y acciones en ergonomía y mantenerlos al día.$txt$, $txt$Existen algunos registros informales, que no necesariamente están actualizados ni completos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 4), 2, $txt$Se recomienda registrar todos los diagnósticos, programas y acciones en ergonomía.$txt$, $txt$Se mantienen registros de algunos diagnósticos, programas o acciones en ergonomía, pero no de todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 4), 3, $txt$Se recomienda completar y mantener al día los registros de diagnósticos, programas y acciones en ergonomía.$txt$, $txt$Se mantienen registros actualizados de la mayoría de los diagnósticos, programas y acciones en ergonomía.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 4), 4, $txt$Se recomienda mantener actualizados y completos los registros de diagnósticos, programas y acciones en ergonomía.$txt$, $txt$Se mantienen registros actualizados y completos de todos los diagnósticos, programas y acciones en ergonomía.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 5), 0, $txt$Se recomienda supervisar que las actividades se realicen en condiciones seguras, conforme al procedimiento de seguridad de la organización.$txt$, $txt$No se supervisa la aplicación de las medidas ergonómicas en los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 5), 1, $txt$Se recomienda establecer un criterio formal para supervisar la aplicación de las medidas ergonómicas.$txt$, $txt$La supervisión de las medidas ergonómicas se realiza de forma esporádica o aislada, sin un criterio establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 5), 2, $txt$Se recomienda extender la supervisión de las medidas ergonómicas a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se supervisa la aplicación de las medidas ergonómicas en algunos puestos de trabajo con manejo manual de cargas, pero no en todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 5), 3, $txt$Se recomienda extender la supervisión sistemática de las medidas ergonómicas a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se supervisa la aplicación de las medidas ergonómicas en la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 5), 4, $txt$Se recomienda mantener la supervisión sistemática de las medidas ergonómicas.$txt$, $txt$Se supervisa de forma sistemática la aplicación de las medidas ergonómicas en todos los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 6), 0, $txt$Se recomienda considerar una auditoría, interna o a través de una unidad de verificación acreditada.$txt$, $txt$No se han realizado auditorías internas ni externas sobre el cumplimiento de la NOM-036-1-STPS-2018.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 6), 1, $txt$Se recomienda realizar una auditoría formal de cumplimiento normativo.$txt$, $txt$Se ha realizado alguna revisión informal del cumplimiento, sin que sea propiamente una auditoría.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 6), 2, $txt$Se recomienda ampliar el alcance de las auditorías a todos los temas de cumplimiento normativo.$txt$, $txt$Se han realizado auditorías de cumplimiento en algunos temas o áreas, pero no de forma integral.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 6), 3, $txt$Se recomienda realizar auditorías de forma periódica y con alcance integral.$txt$, $txt$Se han realizado auditorías internas o externas que cubren la mayoría de los temas de cumplimiento normativo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 6), 4, $txt$Se recomienda mantener las auditorías periódicas de cumplimiento normativo.$txt$, $txt$Se realizan auditorías internas o externas de forma periódica para verificar el cumplimiento normativo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 7), 0, $txt$Se recomienda informar a los trabajadores sobre las posibles alteraciones a la salud, mediante carteles, pláticas, boletines u otro medio.$txt$, $txt$No se ha comunicado al personal la importancia de esta norma ni los riesgos del manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 7), 1, $txt$Se recomienda establecer una comunicación regular sobre la norma y los riesgos del manejo manual de cargas.$txt$, $txt$La importancia de la norma se ha comunicado de forma aislada, sin que sea una práctica constante.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 7), 2, $txt$Se recomienda extender esta comunicación a toda la organización.$txt$, $txt$Se comunica la importancia de esta norma en algunas áreas de la organización, pero no en todas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 7), 3, $txt$Se recomienda extender la comunicación sobre la importancia de la norma a todo el personal.$txt$, $txt$Se comunica la importancia de esta norma a la mayoría del personal, a través de distintos medios, como carteles, folletos o pláticas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 7), 4, $txt$Se recomienda mantener la comunicación constante sobre las alteraciones a la salud derivadas del manejo manual de cargas.$txt$, $txt$Se informa de forma constante a todo el personal sobre las posibles alteraciones a la salud derivadas del manejo manual de cargas, mediante carteles, pláticas y boletines.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 8), 0, $txt$Se recomienda poner a disposición de los trabajadores la información sobre los riesgos por manejo manual de cargas, conforme a lo que exige la norma.$txt$, $txt$La información sobre los riesgos por manejo manual de cargas no está disponible para los trabajadores.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 8), 1, $txt$Se recomienda facilitar de forma proactiva el acceso a la información sobre los riesgos por manejo manual de cargas.$txt$, $txt$La información sobre los riesgos por manejo manual de cargas está disponible de forma limitada, por ejemplo, solo si el trabajador la solicita expresamente.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 8), 2, $txt$Se recomienda poner la información sobre los riesgos por manejo manual de cargas a disposición de todo el personal.$txt$, $txt$La información sobre los riesgos por manejo manual de cargas es accesible para algunos trabajadores, pero no para todo el personal de la organización.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 8), 3, $txt$Se recomienda asegurar que la información sobre los riesgos por manejo manual de cargas sea accesible para todos los trabajadores.$txt$, $txt$La información sobre los riesgos por manejo manual de cargas es accesible para la mayoría de los trabajadores.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 8), 4, $txt$Se recomienda mantener accesible para todos los trabajadores la información sobre los riesgos por manejo manual de cargas.$txt$, $txt$La información sobre los riesgos por manejo manual de cargas está disponible para todos los trabajadores de la organización.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 9), 0, $txt$Se recomienda elaborar el diagnóstico ergonómico e integrarlo al diagnóstico de seguridad y salud en el trabajo que exige la NOM-030-STPS-2009.$txt$, $txt$No se cuenta con ningún diagnóstico ergonómico y, por lo tanto, no se integra al programa anual de seguridad y salud en el trabajo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 9), 1, $txt$Se recomienda integrar los diagnósticos ergonómicos al diagnóstico de seguridad y salud en el trabajo que exige la NOM-030-STPS-2009.$txt$, $txt$Se cuenta con diagnósticos ergonómicos, pero no se integran al programa anual de seguridad y salud en el trabajo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 9), 2, $txt$Se recomienda formalizar la integración de los diagnósticos ergonómicos al programa anual de seguridad y salud en el trabajo.$txt$, $txt$Los diagnósticos ergonómicos se integran de forma parcial o informal al programa anual de seguridad y salud en el trabajo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 9), 3, $txt$Se recomienda integrar todos los diagnósticos ergonómicos al programa anual de seguridad y salud en el trabajo.$txt$, $txt$La mayoría de los diagnósticos ergonómicos se integran al programa anual de seguridad y salud en el trabajo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 9), 4, $txt$Se recomienda mantener la integración de los diagnósticos ergonómicos al programa anual de seguridad y salud en el trabajo.$txt$, $txt$Todos los diagnósticos ergonómicos se integran al programa anual de seguridad y salud en el trabajo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 10), 0, $txt$Se recomienda impulsar acciones que fomenten una cultura de prevención y ergonomía entre el personal.$txt$, $txt$No se promueve una cultura de prevención o ergonomía dentro de la organización.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 10), 1, $txt$Se recomienda dar continuidad a las acciones de promoción de la cultura de prevención y ergonomía.$txt$, $txt$Se han realizado algunas acciones aisladas para promover una cultura de prevención y ergonomía, sin continuidad.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 10), 2, $txt$Se recomienda extender la promoción de la cultura de prevención y ergonomía a toda la organización.$txt$, $txt$Se promueve una cultura de prevención y ergonomía en algunas áreas de la organización, pero no en todas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 10), 3, $txt$Se recomienda extender la promoción de la cultura de prevención y ergonomía a toda la organización.$txt$, $txt$Se promueve una cultura de prevención y ergonomía en la mayor parte de la organización.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 4) and i.numero = 10), 4, $txt$Se recomienda mantener la cultura de prevención y ergonomía mediante acciones continuas.$txt$, $txt$Existe una cultura consolidada de prevención y ergonomía en toda la organización.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 4), 'inexistente', 'apertura', $txt$No existe un proceso formal de difusión ni de registro de políticas y estrategias ergonómicas dentro de la organización.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 4), 'minimo', 'apertura', $txt$La difusión y el registro de políticas y estrategias ergonómicas se encuentran en un nivel Mínimo: la mayoría de las acciones de comunicación, registro y seguimiento no están cubiertas.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 4), 'regular', 'apertura', $txt$La difusión y el registro de políticas y estrategias ergonómicas se encuentran en un nivel Regular: existen avances, pero persisten vacíos relevantes.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 4), 'aceptable', 'apertura', $txt$La difusión y el registro de políticas y estrategias ergonómicas presentan un nivel Aceptable, con puntos específicos por reforzar.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 4), 'optimo', 'apertura', $txt$La difusión y el registro de políticas y estrategias ergonómicas están consolidados.$txt$);
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 1), 0, $txt$Se recomienda elaborar el análisis que integra la identificación de actividades, la estimación del nivel de riesgo y, en su caso, la evaluación específica.$txt$, $txt$No se cuenta con ningún diagnóstico enfocado en identificar los factores de riesgo ergonómico por manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 1), 1, $txt$Se recomienda elaborar el diagnóstico a partir de las condiciones de trabajo conocidas, integrando la identificación de actividades, la estimación del nivel de riesgo y, en su caso, la evaluación específica.$txt$, $txt$Se conocen las condiciones de trabajo que involucran manejo manual de cargas, pero no se cuenta con ningún diagnóstico.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 1), 2, $txt$Se recomienda completar el diagnóstico y extenderlo a todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$Se cuenta con un diagnóstico parcial o informal que identifica algunos factores de riesgo, pero no cubre todos los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 1), 3, $txt$Se recomienda completar el diagnóstico en todos los puestos de trabajo con manejo manual de cargas y mantenerlo actualizado.$txt$, $txt$Se cuenta con un diagnóstico que identifica los factores de riesgo ergonómico en la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 1), 4, $txt$Se recomienda mantener actualizado el diagnóstico de factores de riesgo ergonómico.$txt$, $txt$Se cuenta con un diagnóstico completo que identifica los factores de riesgo ergonómico en todos los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 2), 0, $txt$Se recomienda aplicar una evaluación específica del nivel de riesgo (por ejemplo, la ecuación de NIOSH o el método de la norma ISO 11228-2 para empujar o jalar) cuando la estimación simple no permita determinar el nivel de riesgo, o cuando persista algún peligro después de aplicar medidas correctivas.$txt$, $txt$No se ha aplicado ningún método de evaluación ergonómica (como NIOSH, REBA, MAC Tool o RAPP Tool) a los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 2), 1, $txt$Se recomienda aplicar de forma completa y sistemática un método de evaluación ergonómica.$txt$, $txt$Se ha intentado aplicar algún método de evaluación ergonómica, pero de forma incompleta o no sistemática.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 2), 2, $txt$Se recomienda extender la aplicación del método de evaluación ergonómica a todos los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$, $txt$Se aplica algún método de evaluación ergonómica en algunos puestos de trabajo con manejo manual de cargas, pero no en todos los que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 2), 3, $txt$Se recomienda extender la evaluación ergonómica a todos los puestos de trabajo con manejo manual de cargas que lo requieren y documentar los resultados.$txt$, $txt$Se aplica un método de evaluación ergonómica en la mayoría de los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 2), 4, $txt$Se recomienda mantener la aplicación documentada del método de evaluación ergonómica.$txt$, $txt$Se aplica y documenta un método de evaluación ergonómica validado en todos los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 3), 0, $txt$Se recomienda adoptar medidas de control técnicas cuando el análisis de riesgo así lo indique.$txt$, $txt$No se aplica ninguna medida técnica, como redistribución de espacios o adecuación de estaciones, para reducir los riesgos identificados.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 3), 1, $txt$Se recomienda basar los ajustes técnicos en los resultados del análisis de riesgo.$txt$, $txt$Se han hecho algunos ajustes técnicos aislados, que no responden a un análisis de riesgo.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 3), 2, $txt$Se recomienda extender las medidas técnicas a todas las áreas o estaciones de trabajo con manejo manual de cargas que lo requieren.$txt$, $txt$Se aplican medidas técnicas en algunas áreas o estaciones de trabajo con manejo manual de cargas, pero no en todas las que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 3), 3, $txt$Se recomienda extender las medidas técnicas a todas las áreas o estaciones de trabajo con manejo manual de cargas que lo requieren.$txt$, $txt$Se aplican medidas técnicas en la mayoría de las áreas o estaciones de trabajo con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 3), 4, $txt$Se recomienda mantener las medidas técnicas implementadas y revisarlas cuando cambien las condiciones de trabajo.$txt$, $txt$Se aplican medidas técnicas (redistribución de espacios, adecuación de estaciones, modificación de procesos o equipos) en todas las áreas con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 4), 0, $txt$Se recomienda adoptar alguna de estas medidas cuando el análisis de riesgo lo indique.$txt$, $txt$No se han implementado medidas administrativas, como rotación de puestos de trabajo o pausas activas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 4), 1, $txt$Se recomienda formalizar las medidas administrativas con un criterio establecido.$txt$, $txt$Se aplican medidas administrativas de forma informal u ocasional, sin un criterio establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 4), 2, $txt$Se recomienda extender las medidas administrativas a todos los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$, $txt$Se implementan medidas administrativas en algunos puestos de trabajo con manejo manual de cargas, pero no en todos los que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 4), 3, $txt$Se recomienda extender las medidas administrativas a todos los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$, $txt$Se implementan medidas administrativas en la mayoría de los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 4), 4, $txt$Se recomienda mantener la aplicación sistemática de las medidas administrativas.$txt$, $txt$Se implementan de forma sistemática medidas administrativas (rotación de puestos, pausas activas, reprogramación de actividades) en todos los puestos de trabajo con manejo manual de cargas que lo requieren.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 5), 0, $txt$Se recomienda elaborar uno que incluya los puestos de trabajo sujetos al programa, las medidas de control, las fechas programadas, el responsable de su ejecución y la evaluación posterior.$txt$, $txt$No se cuenta con ningún programa formal de ergonomía.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 5), 1, $txt$Se recomienda formalizar el programa de ergonomía con todos los elementos que exige la norma.$txt$, $txt$Existe un programa informal que no cumple con todos los elementos que exige la norma.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 5), 2, $txt$Se recomienda completar el programa de ergonomía con el cronograma, el responsable asignado y los demás elementos faltantes.$txt$, $txt$El programa de ergonomía existe, pero le faltan elementos como el cronograma o el responsable asignado.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 5), 3, $txt$Se recomienda completar y mantener actualizado el programa de ergonomía.$txt$, $txt$El programa de ergonomía cuenta con la mayoría de sus elementos (puestos de trabajo, medidas, fechas, responsable).$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 5), 4, $txt$Se recomienda mantener actualizado el programa de ergonomía.$txt$, $txt$Se cuenta con un programa formal de ergonomía completo, con responsables y cronograma para la implementación de mejoras.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 6), 0, $txt$Se recomienda dar seguimiento clínico a estos casos, conforme al programa de vigilancia a la salud.$txt$, $txt$No se da ningún seguimiento a los casos de trastornos musculoesqueléticos en el personal.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 6), 1, $txt$Se recomienda establecer un procedimiento de seguimiento de los casos de trastornos musculoesqueléticos.$txt$, $txt$El seguimiento a los casos de trastornos musculoesqueléticos se realiza de manera informal, sin un procedimiento establecido.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 6), 2, $txt$Se recomienda extender este seguimiento a todos los casos identificados.$txt$, $txt$Se da seguimiento a algunos casos de trastornos musculoesqueléticos, pero se desconoce si se atiende a todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 6), 3, $txt$Se recomienda dar seguimiento a todos los casos de trastornos musculoesqueléticos identificados.$txt$, $txt$Se da seguimiento a la mayoría de los casos de trastornos musculoesqueléticos identificados.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 6), 4, $txt$Se recomienda mantener el seguimiento completo y oportuno de los casos de trastornos musculoesqueléticos.$txt$, $txt$Se da un seguimiento completo y oportuno a todos los casos de trastornos musculoesqueléticos identificados.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 7), 0, $txt$Se recomienda considerar la aplicación de un cuestionario específico como una de las formas que permite la norma para detectar síntomas musculoesqueléticos.$txt$, $txt$No se ha aplicado ningún cuestionario específico (por ejemplo, el Cuestionario Nórdico de Kuorinka) para detectar síntomas musculoesqueléticos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 7), 1, $txt$Se recomienda ampliar la aplicación del cuestionario a los trabajadores ocupacionalmente expuestos al manejo manual de cargas.$txt$, $txt$Se ha aplicado un cuestionario específico de forma aislada, a muy pocos trabajadores.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 7), 2, $txt$Se recomienda establecer una periodicidad para la aplicación del cuestionario de síntomas musculoesqueléticos.$txt$, $txt$Se aplica un cuestionario específico a algunos grupos de trabajadores, pero no de forma regular.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 7), 3, $txt$Se recomienda aplicar el cuestionario a todos los trabajadores ocupacionalmente expuestos al manejo manual de cargas.$txt$, $txt$Se aplica un cuestionario específico, de forma periódica, a la mayoría de los trabajadores ocupacionalmente expuestos al manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
