insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 8), 0, $txt$Se recomienda generar reportes de mejora continua para dar seguimiento a los avances del programa de ergonomía.$txt$, $txt$No se generan reportes de mejora continua en materia de ergonomía.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 8), 1, $txt$Se recomienda establecer un formato y una periodicidad para los reportes de mejora continua en ergonomía.$txt$, $txt$Se generan reportes de forma esporádica, sin un formato ni una periodicidad establecidos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
