insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 9), 0, $txt$Se recomienda incluir este tema en la capacitación, junto con los efectos a la salud de la exposición a estos factores de riesgo.$txt$, $txt$No se capacita al personal para autodetectar síntomas musculoesqueléticos relacionados con el manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 9), 1, $txt$Se recomienda incorporar la autodetección de síntomas musculoesqueléticos a la capacitación formal.$txt$, $txt$Se ha dado información aislada sobre la autodetección de síntomas musculoesqueléticos, sin que forme parte de la capacitación formal.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
