insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 9), 4, $txt$Se recomienda mantener la capacitación en autodetección de síntomas musculoesqueléticos para todo el personal ocupacionalmente expuesto.$txt$, $txt$Se capacita a todo el personal ocupacionalmente expuesto en la autodetección de síntomas musculoesqueléticos relacionados con el manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 10), 0, $txt$Se recomienda que el programa de ergonomía, al elaborarse, describa con claridad las medidas de control técnicas y administrativas para cada puesto de trabajo con manejo manual de cargas.$txt$, $txt$No se cuenta con ningún programa de ergonomía.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 10), 1, $txt$Se recomienda detallar en el programa de ergonomía cómo se aplica cada medida de prevención y control.$txt$, $txt$El programa de ergonomía describe las medidas de prevención y control de forma general, sin precisar cómo se aplican.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 10), 2, $txt$Se recomienda describir con claridad las medidas de prevención y control para todos los puestos de trabajo con manejo manual de cargas.$txt$, $txt$El programa de ergonomía describe con claridad las medidas de prevención y control para algunos puestos de trabajo con manejo manual de cargas, pero no para todos.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
insert into nom036.recomendacion (item_id, nivel, texto, descripcion_nivel) values ((select i.id from nom036.item i where i.criterio_id = (select c.id from nom036.criterio c where c.numero = 5) and i.numero = 10), 3, $txt$Se recomienda completar la descripción de las medidas para todos los puestos de trabajo con manejo manual de cargas y mantener actualizado el programa.$txt$, $txt$El programa de ergonomía describe con claridad las medidas de prevención y control para la mayoría de los puestos de trabajo con manejo manual de cargas.$txt$) on conflict (item_id, nivel) do update set texto = excluded.texto, descripcion_nivel = excluded.descripcion_nivel;
