insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 5), 'inexistente', 'apertura', $txt$No existe un proceso formal de medidas de prevención y control de los factores de riesgo ergonómico por manejo manual de cargas, conforme a lo que exige el Capítulo 8 de la NOM-036-1-STPS-2018.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 5), 'minimo', 'apertura', $txt$Las medidas de prevención y control de los factores de riesgo ergonómico por manejo manual de cargas se encuentran en un nivel Mínimo: la mayoría de los elementos que exige el Capítulo 8 de la NOM-036-1-STPS-2018 no están cubiertos.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 5), 'regular', 'apertura', $txt$Las medidas de prevención y control de los factores de riesgo ergonómico por manejo manual de cargas se encuentran en un nivel Regular: existen avances, pero persisten vacíos relevantes.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 5), 'aceptable', 'apertura', $txt$Las medidas de prevención y control de los factores de riesgo ergonómico por manejo manual de cargas presentan un nivel Aceptable, con puntos específicos por reforzar.$txt$);
insert into nom036.plantilla_bucket (criterio_id, bucket, tipo, texto) values ((select c.id from nom036.criterio c where c.numero = 5), 'optimo', 'apertura', $txt$Las medidas de prevención y control de los factores de riesgo ergonómico por manejo manual de cargas están consolidadas.$txt$);
